INSERT INTO "Treatment" (id, slug, name, description, "durationMin", price, currency, category, status, "sortOrder", "createdAt", "updatedAt") VALUES
  (gen_random_uuid(), 'deepcore-massage',         'Deepcore Massage (45 min)',             'A unique combination of deep tissue, trigger points and energy flow. Releases deep tension while restoring the body''s natural energy pathways.',          45,   350,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 0, now(), now()),
  (gen_random_uuid(), 'deepcore-massage-60',      'Deepcore Massage (60 min)',             'Extended deepcore session: deep tissue, trigger points and energy flow for a deeper release.',                                                              60,   400,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 1, now(), now()),
  (gen_random_uuid(), 'couples-massage',          'Couples Massage (45 min)',              'Simultaneous massage for two in the same room. Share the experience of relaxation together.',                                                               45,   550,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 2, now(), now()),
  (gen_random_uuid(), 'couples-massage-60',       'Couples Massage (60 min)',              'Extended couples massage: simultaneous relaxation for two in the same room.',                                                                               60,   700,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 3, now(), now()),
  (gen_random_uuid(), 'swedish-massage',          'Swedish Massage (45 min)',              'Improves blood flow, reduces tension and enhances flexibility. A classic relaxation massage using long, flowing strokes.',                                  45,   300,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 4, now(), now()),
  (gen_random_uuid(), 'swedish-massage-60',       'Swedish Massage (60 min)',              'Extended Swedish massage for deeper relaxation and full-body tension release.',                                                                             60,   350,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 5, now(), now()),
  (gen_random_uuid(), 'holistic-massage',         'Holistic Massage (45 min)',             'Treats body, mind and spirit to balance energy and promote wellbeing. A whole-person approach to restoration.',                                            45,   330,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 6, now(), now()),
  (gen_random_uuid(), 'holistic-massage-60',      'Holistic Massage (60 min)',             'Extended holistic massage treating body, mind and spirit for complete restoration.',                                                                        60,   380,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 7, now(), now()),
  (gen_random_uuid(), 'reflexology',              'Reflexology (30 min)',                  'Pressure applied to feet, hands and ears to restore balance. A deeply relaxing treatment working on the body''s reflex points.',                           30,   200,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 8, now(), now()),
  (gen_random_uuid(), 'reflexology-45',           'Reflexology (45 min)',                  'Extended reflexology: pressure applied to feet, hands and ears for deeper balance restoration.',                                                            45,   250,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 9, now(), now()),
  (gen_random_uuid(), 'pedicure',                 'Pedicure',                             'Cleaning, exfoliating and moisturising of feet and toenails. A complete foot treatment to leave you refreshed.',                                            45,   150,  'GHS', 'Ko-Sa Health Spa', 'PUBLISHED', 10, now(), now()),
  (gen_random_uuid(), 'herbal-detox-steam',       'Herbal Detox Steam Ritual',            'Circulation, relaxation and cleansing. A deeply purifying steam ritual using herbal blends to detoxify and restore the body.',                             60,   264,  'GHS', 'O2 Wellness',      'PUBLISHED', 0, now(), now()),
  (gen_random_uuid(), 'glow-polish-facial',       'Glow Polish Facial Ritual',            'Radiance, hydration and skin refresh. A revitalising facial treatment to restore your natural glow.',                                                       60,   302,  'GHS', 'O2 Wellness',      'PUBLISHED', 1, now(), now()),
  (gen_random_uuid(), 'full-body-glow-polish',    'Full Body Glow Polish',                'Exfoliation, skin renewal and softening. A full-body scrub that leaves skin silky and luminous.',                                                           75,   672,  'GHS', 'O2 Wellness',      'PUBLISHED', 2, now(), now()),
  (gen_random_uuid(), '1-day-regenerative-escape','1-Day Regenerative Escape',            'Therapy, meal and wellness consultation. A full day of restoration combining treatments, nourishment and personalised wellness guidance.',                  480,  1200, 'GHS', 'O2 Wellness',      'PUBLISHED', 3, now(), now()),
  (gen_random_uuid(), '2-day-coastal-reset',      '2-Day Coastal Reset Retreat',          'Therapies, meals and guided wellness reset. Two days of immersive coastal wellness to fully recharge.',                                                     960,  2400, 'GHS', 'O2 Wellness',      'PUBLISHED', 4, now(), now()),
  (gen_random_uuid(), '3-day-full-renewal',       '3-Day Full Renewal Retreat',           'Immersive healing, meals and premium therapies. Three days of comprehensive renewal combining Ko-Sa''s best wellness offerings.',                           1440, 3600, 'GHS', 'O2 Wellness',      'PUBLISHED', 5, now(), now());
